      if(!response.ok)B.fail([401,403,429].includes(response.status)?'ACCESS_DENIED':'SEARCH_FAILED','게시판 검색 실패 (HTTP '+response.status+'). 기본 검색을 확인해 주세요.');
      const limit=3*1024*1024;if(Number(response.headers?.get('content-length'))>limit)B.fail('RESOURCE_LIMIT','검색 HTML 응답이 3MB를 넘었습니다.');
      let html='';if(response.body?.getReader){const r=response.body.getReader(),decoder=new TextDecoder();let bytes=0;try{while(true){const x=await r.read();if(x.done)break;bytes+=x.value.byteLength;if(bytes>limit){await r.cancel();B.fail('RESOURCE_LIMIT','검색 HTML 응답이 3MB를 넘었습니다.');}html+=decoder.decode(x.value,{stream:true});}html+=decoder.decode();}finally{r.releaseLock();}}
