      if(controller.signal.aborted)B.fail('ABORTED','검색을 취소했습니다.');
      const t=g.document.createElement('template');t.innerHTML=html;return t.content;
    }catch(e){if(controller.signal.aborted)B.fail(signal?.aborted?'ABORTED':'TIMEOUT',signal?.aborted?'검색을 취소했습니다.':'검색 시간이 초과되었습니다.');throw e;}
    finally{g.clearTimeout(timer);signal?.removeEventListener('abort',abort);}
  }
  class BoardSearch{
    constructor({origin=g.location.origin,readHTML=readSearchHTML,ttl=60000,now=()=>Date.now()}={}){Object.assign(this,{origin,readHTML,ttl,now,cache:new Map(),pending:new Map(),stopped:false});}
    search(query,page=1,{force=false}={}){
      if(this.stopped)return Promise.reject(Object.assign(new Error('생성기를 다시 열어 주세요.'),{code:'ABORTED'}));
      const url=searchUrl(query,page,this.origin),hit=this.cache.get(url);if(!force&&hit&&this.now()-hit.time<this.ttl)return Promise.resolve(B.clone(hit.result));
      if(this.pending.has(url))return this.pending.get(url).promise;
      if(this.pending.size)B.fail('SEARCH_BUSY','진행 중인 검색을 취소한 뒤 다시 검색해 주세요.');
      const controller=new g.AbortController();const promise=(async()=>{const doc=await this.readHTML(url,{signal:controller.signal});if(controller.signal.aborted)B.fail('ABORTED','검색을 취소했습니다.');const result=parseSearch(doc,{query,page,origin:this.origin});if(this.cache.size>=20)this.cache.delete(this.cache.keys().next().value);this.cache.set(url,{time:this.now(),result});return B.clone(result);})().finally(()=>this.pending.delete(url));
