    destroy(){this.stopped=true;this.cancel();this.cache.clear();}
  }
  class SearchSelection{
    constructor(){this.query=null;this.items=[];this.selected=new Map();this.anchor=null;}
    set(result){if(result.query!==this.query){this.selected.clear();this.query=result.query;}this.items=result.items;this.anchor=null;}
    click(index,{shiftKey=false,ctrlKey=false,metaKey=false,checkbox=false}={}){
      const item=this.items[index];if(!item)return;
      if(shiftKey&&this.anchor!==null){if(!ctrlKey&&!metaKey&&!checkbox)this.selected.clear();for(let i=Math.min(index,this.anchor);i<=Math.max(index,this.anchor);i++)this.selected.set(this.items[i].articleId,this.items[i]);}
      else{if(!ctrlKey&&!metaKey&&!checkbox)this.selected.clear();if((ctrlKey||metaKey||checkbox)&&this.selected.has(item.articleId))this.selected.delete(item.articleId);else this.selected.set(item.articleId,item);this.anchor=index;}
    }
    all(){for(const item of this.items)this.selected.set(item.articleId,item);}
    clear(){this.selected.clear();this.anchor=null;}
    ordered(){return [...this.selected.values()].sort((a,b)=>a.page-b.page||a.index-b.index);}
  }
