(function(g){
  'use strict';const B=g.AruBundle;
  const CSS=`:host{all:initial;font:14px system-ui;color:#30283e}.shade{position:fixed;inset:0;background:#201b3755;z-index:2147483600;display:grid;place-items:center}.dialog{width:min(960px,94vw);max-height:92vh;background:#fff;border-radius:14px;display:flex;flex-direction:column;box-shadow:0 20px 90px #211b3555}header,footer{padding:16px;display:flex;gap:10px;align-items:center;border-bottom:1px solid #e4deed}header strong{font-size:19px;flex:1}main{padding:18px;overflow:auto}footer{border-top:1px solid #e4deed;border-bottom:0;flex-wrap:wrap}button,input,textarea{font:inherit;box-sizing:border-box}button{cursor:pointer;border:1px solid #d7c7ec;border-radius:7px;padding:8px 12px;background:#f6f1fc;color:#513378}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #b58ee6;outline-offset:2px}.primary{background:#724daf;color:white}label{display:block;margin:12px 0}input{width:100%;border:1px solid #d6c9e8;border-radius:7px;padding:10px}small,.hint{color:#706279;font-size:12px;line-height:1.65}.lookup{display:flex;gap:8px}.lookup input{flex:1;min-width:100px}.status{padding:10px;background:#f5f0fc;white-space:pre-wrap;border-radius:7px;margin:12px 0}.status.error{background:#fff0eb;color:#993526}.refs{padding:0;list-style:none;max-height:380px;overflow:auto}.row{padding:12px;border:1px solid #e6ddee;border-radius:8px;margin:8px 0;background:#fdfbff}.row-head{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.row-head strong{flex:1;min-width:180px}.actions{display:flex;gap:5px}.actions button{padding:6px}.info{display:block;margin-top:5px}.drag{color:#887695;cursor:grab}.row.drag-over{outline:2px solid #9974cd}.preview{border:1px solid #ddd1ee;border-radius:8px;padding:14px;background:#faf7ff}.preview ol{max-height:200px;overflow:auto}textarea{width:100%;height:150px;border:1px solid #ddd;padding:8px}img{max-width:96px;max-height:96px;display:block}details{margin-top:8px}.empty{color:#7d7188}.close{background:#fff}.busy-note{min-height:22px}@media(max-width:600px){.lookup{flex-wrap:wrap}.lookup input{flex-basis:100%}.actions{flex-wrap:wrap}header,footer,main{padding:12px}.dialog{max-height:96vh}.row-head strong{min-width:100%}}`;
  class Panel{
    constructor({document=g.document,client,token,browser=B.Browser,reader=new B.SourceReader(),searcher,onClose=()=>{}}){
      Object.assign(this,{doc:document,client,token,browser,reader,onClose,draft:new B.Draft(),busy:false,closed:false,ready:false,preview:null,dragId:null,page:0,pageSize:50});
      this.host=this.doc.createElement('div');this.host.dataset.aruBundlePanel='';this.shadow=this.host.attachShadow({mode:'open'});
      this.shadow.innerHTML=`<style>${CSS}</style><div class="shade"><section class="dialog" role="dialog" aria-modal="true" aria-label="아이콘 통합"><header><strong>아이콘 통합</strong><button type="button" class="close" aria-label="닫기"><svg class="aru-ui-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><main><p class="hint">원본 게시글을 모아 통합팩을 만듭니다. 게시글 저장은 직접 진행하세요.</p><p class="context hint"></p><label>통합팩 제목<input class="name" maxlength="240" placeholder="통합 아이콘팩 제목"></label><label for="aru-bundle-url">원본 아이콘 공유 게시글 URL</label><div class="lookup"><input id="aru-bundle-url" class="url" type="url" placeholder="https://bbs.ruliweb.com/community/board/98/read/…"><button type="button" class="add">조회 · 추가</button><button type="button" class="cancel" disabled>조회 취소</button></div><div class="status" role="status" aria-live="polite">에디터 확인 중…</div><p class="hint">드래그하거나 위·아래 버튼으로 순서를 바꾸세요.</p><ul class="refs" aria-label="원본 글별 그룹"></ul><div class="preview" hidden></div></main><footer><button type="button" class="save">초안 저장</button><button type="button" class="load">초안 불러오기</button><button type="button" class="generate">변경 미리보기</button><button type="button" class="apply primary" disabled>편집기에 적용</button></footer></section></div>`;this.uiCleanup=g.AruIcons?.DesignSystem?.attach(this.shadow);
      g.AruIcons?.DesignSystem?.modalHeader(this.shadow.querySelector('header'),{kind:'bundle',description:'아이콘 공유 게시글을 통합팩으로 구성합니다.'});
      this.doc.body.append(this.host);this.q=s=>this.shadow.querySelector(s);
      this.search=new B.SearchPanel(this,searcher);this.revision=0;this.invalidReason='에디터 연결 확인 중입니다.';
      const reason=this.doc.createElement('p');reason.className='apply-reason';reason.setAttribute('role','status');this.q('footer').append(reason);
      this.q('footer').append(this.button('에디터 다시 연결',()=>{if(!this.busy)this.init();},'에디터 다시 연결'));
      this.q('.close').onclick=()=>this.close();this.q('.name').oninput=()=>{this.draft.name=this.q('.name').value;this.invalidate();};
      this.q('.url').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();this.add();}};this.q('.add').onclick=()=>this.add();this.q('.cancel').onclick=()=>this.reader.cancel();
      this.q('.generate').onclick=()=>this.generate();this.q('.apply').onclick=()=>this.apply();this.q('.save').onclick=()=>this.save();this.q('.load').onclick=()=>this.load();
      const paging=this.doc.createElement('div');paging.className='pages';this.pageLabel=this.doc.createElement('small');paging.append(this.button('이전 목록',()=>{if(this.busy||this.page===0)return;this.page--;this.render();}),this.pageLabel,this.button('다음 목록',()=>{if(this.busy||this.page+1>=Math.ceil(this.draft.rows.length/this.pageSize))return;this.page++;this.render();}));this.q('.refs').after(paging);
      this.key=e=>{if(e.key==='Escape'){e.preventDefault();this.close();}if(e.key==='Tab'){const nodes=[...this.shadow.querySelectorAll('button,input,summary,textarea')].filter(n=>!n.disabled&&!n.closest('[hidden]'));const first=nodes[0],last=nodes.at(-1),active=this.shadow.activeElement;if(e.shiftKey&&active===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&active===last){e.preventDefault();first?.focus();}}};this.shadow.addEventListener('keydown',this.key);this.controls();this.init();
    }
    async init(){if(this.session)await this.client.request('release',{session:this.session}).catch(()=>{});this.ready=false;this.controls();try{const r=await this.client.request('scan',{token:this.token});if(this.closed){this.client.request('release',{session:r.session}).catch(()=>{});return;}this.session=r.session;this.articleId=r.articleId;if(!this.initialized){this.draft=new B.Draft(r.value);this.q('.name').value=this.draft.name;this.initialized=true;}this.ready=true;this.q('.context').textContent=this.articleId?'대표 게시글: 98/'+this.articleId:'신규 작성: 대표 글 번호가 아직 없습니다.';this.render();this.message(r.value?'기존 통합팩을 불러왔습니다.':'통합할 개별 아이콘 게시글을 추가하세요.');this.q('.name').focus();this.invalidate();}catch(e){this.invalidReason='['+(e.code||'EDITOR_UNAVAILABLE')+'] '+e.message;this.message(this.invalidReason,true);}finally{this.controls();}}
