/* Local download records; deliberately separate from public aru-icons metadata. */
(function (root) {
  'use strict';
  const D = root.AruBodyDownload = root.AruBodyDownload || {};
  const HOSTS = ['i1.ruliweb.com','i2.ruliweb.com','i3.ruliweb.com'];
  const JOB_KEY = 'aruBodyDownloadJobV1';
  const error = (code, message) => Object.assign(new Error(message), {code});
  function article(url) {
    let u; try {u = new URL(url);} catch (_) {throw error('PAGE_URL','게시글 주소를 확인할 수 없습니다.');}
    const match = u.pathname.match(/^\/community\/board\/98\/read\/([1-9]\d{0,14})\/?$/);
    if (u.protocol !== 'https:' || !['bbs.ruliweb.com','m.ruliweb.com'].includes(u.hostname) || u.port || u.username || u.password || !match)
      throw error('PAGE_URL','아이콘 공유 게시판의 게시글 읽기 페이지에서 실행해 주세요.');
    return {site:'ruliweb',boardId:98,articleId:match[1],url:u.origin+'/community/board/98/read/'+match[1]};
  }
  function mediaUrl(value, base) {
    if (typeof value !== 'string' || value.length > 2048 || /[\u0000-\u0020\u007f\\]/u.test(value)) throw error('MEDIA_URL','안전하지 않은 이미지 주소입니다.');
    let u; try {u = new URL(value, base);} catch (_) {throw error('MEDIA_URL','이미지 주소를 해석할 수 없습니다.');}
    if (u.protocol !== 'https:' || !HOSTS.includes(u.hostname) || u.username || u.password || u.port || u.hash)
      throw error('MEDIA_URL','허용된 루리웹 이미지 CDN 주소가 아닙니다.');
    return u.href;
  }
  function safeName(value, max=100) {
    let text=String(value || '').normalize('NFC').replace(/[<>:"/\\|?*\u0000-\u001f\u007f]/gu,'_').replace(/\s+/gu,' ').trim().replace(/^[. ]+|[. ]+$/gu,'');
    if (!text) text='제목 없음';
    if (/^(?:con|prn|aux|nul|com[1-9¹²³]|lpt[1-9¹²³])(?:\.|$)/iu.test(text)) text='_'+text;
    text=[...text].slice(0,max).join('').replace(/[. ]+$/u,'');
    // Keep UTF-16 paths short even for non-BMP titles.
    while (text.length > max) text=[...text].slice(0,-1).join('');
    return text || '제목 없음';
  }
  function folder(source, runId) {
    const suffix=String(runId).replace(/[^a-zA-Z0-9-]/g,'').slice(0,30);
    if (!suffix) throw error('RUN_ID','다운로드 실행 식별자가 없습니다.');
    return 'Aru-Icons/'+safeName(source.title,75)+' ('+source.articleId+')/'+suffix;
  }
  function originalFilename(url) {
    const value=new URL(url).pathname.split('/').pop();
    try {return decodeURIComponent(value);} catch (_) {return value;}
  }
  function numbered(index, ext) {return String(index).padStart(3,'0')+'.'+ext;}
  function streamMedia(value, mime='') {
    const type=String(mime).split(';')[0].trim().toLowerCase();
    if (['application/vnd.apple.mpegurl','application/x-mpegurl','audio/mpegurl','audio/x-mpegurl','application/dash+xml','video/mp2t'].includes(type)) return true;
    try {return /\.(?:m3u8|mpd|m4s|ts)$/i.test(new URL(value).pathname);} catch (_) {return false;}
  }
  // Container metadata only: skip compressed payloads, never decode or reencode them.
  function isoMedia(b) {
    const text=(p,n)=>String.fromCharCode(...b.subarray(p,p+n));
    const u32=p=>b[p]*16777216+b[p+1]*65536+b[p+2]*256+b[p+3];
    let budget=4096,encrypted=false;
    function boxes(start,end,depth=0) {
      if(depth>16)throw Error('depth');
      const result=[];
      for(let p=start;p<end;){
        if(--budget<0 || p+8>end)throw Error('box');
        let size=u32(p),head=8;const type=text(p+4,4);
        if(size===1){if(p+16>end)throw Error('large box');size=u32(p+8)*4294967296+u32(p+12);head=16;}
        if(size===0)size=end-p;
        if(!Number.isSafeInteger(size) || size<head || p+size>end)throw Error('size');
        const data=p+head,limit=p+size;result.push({type,data,end:limit});
        if(['pssh','encv','enca','sinf'].includes(type))encrypted=true;
        if(['moov','trak','mdia','minf','stbl','mvex','moof','traf','sinf','schi'].includes(type))boxes(data,limit,depth+1);
        if(type==='stsd'){if(data+8>limit)throw Error('stsd');boxes(data+8,limit,depth+1);}
        // Visual sample entries have 78 bytes before child boxes (ISO BMFF).
        if(['avc1','avc3','hvc1','hev1','av01','vp08','vp09','encv'].includes(type) && data+78<limit)boxes(data+78,limit,depth+1);
        p=limit;
      }
      return result;
    }
    try {
      const top=boxes(0,b.length),ftyp=top.find(x=>x.type==='ftyp');
      if(!ftyp || ftyp.data+8>ftyp.end || (ftyp.end-ftyp.data)%4) return null;
      const brands=[text(ftyp.data,4)];for(let p=ftyp.data+8;p+4<=ftyp.end;p+=4)brands.push(text(p,4));
      if(brands.some(x=>['avif','avis'].includes(x)))return {ext:'avif',mime:'image/avif',mediaKind:'image'};
      if(brands.some(x=>['qt  ','heic','heix','hevc','hevx'].includes(x)))return null;
      if(!brands.some(x=>/^(?:isom|iso[2-9]|mp4[12]|avc1|M4V )$/.test(x)))return null;
      if(encrypted)return {ext:null,mime:'video/mp4',reason:'encrypted-media'};
      // Init segments and isolated media fragments are not standalone downloads.
      if(!top.some(x=>x.type==='moov') || !top.some(x=>x.type==='mdat' && x.end>x.data))return null;
      return {ext:'mp4',mime:'video/mp4',mediaKind:'video'};
    } catch (_) {return null;}
  }
  function webmMedia(b) {
    let budget=4096,encrypted=false;
    function vint(p,asId=false) {
      if(p>=b.length || !b[p])throw Error('vint');
      let n=1,mask=128;while(!(b[p]&mask)){n++;mask>>=1;}
      if(n>(asId?4:8) || p+n>b.length)throw Error('vint length');
      let value=asId?b[p]:b[p]&(mask-1),unknown=!asId && value===mask-1;
      for(let i=1;i<n;i++){value=value*256+b[p+i];unknown=unknown && b[p+i]===255;}
      if(!unknown && !Number.isSafeInteger(value))throw Error('vint range');
      return {value,n,unknown};
    }
    function elements(start,end,depth=0) {
      if(depth>16)throw Error('depth');const list=[];
      for(let p=start;p<end;){
        if(--budget<0)throw Error('budget');
        const id=vint(p,true),size=vint(p+id.n),data=p+id.n+size.n;
        if(size.unknown && ![0x18538067,0x1f43b675].includes(id.value))throw Error('unknown size');
        const limit=size.unknown?end:data+size.value;
        if(data>end || limit>end)throw Error('element size');
        list.push({id:id.value,data,end:limit});
        if([0x6d80,0x5035].includes(id.value))encrypted=true; // ContentEncodings / ContentEncryption
        if([0x18538067,0x1654ae6b,0xae,0x6d80,0x6240].includes(id.value))elements(data,limit,depth+1);
        p=limit;
      }
      return list;
    }
    try {
      const top=elements(0,b.length),header=top[0];
      if(header?.id!==0x1a45dfa3)return null;
      const doc=elements(header.data,header.end).find(x=>x.id===0x4282);
      if(!doc || String.fromCharCode(...b.subarray(doc.data,doc.end))!=='webm')return null;
      const segment=top.find(x=>x.id===0x18538067);if(!segment)return null;
      const children=elements(segment.data,segment.end);
      if(encrypted)return {ext:null,mime:'video/webm',reason:'encrypted-media'};
      if(!children.some(x=>x.id===0x1654ae6b) || !children.some(x=>x.id===0x1f43b675 && x.end>x.data))return null;
      return {ext:'webm',mime:'video/webm',mediaKind:'video'};
    } catch (_) {return null;}
  }
  function signature(bytes) {
    const b=bytes, s=(start,count)=>String.fromCharCode(...b.subarray(start,start+count));
    if (b.length>=8 && [137,80,78,71,13,10,26,10].every((v,i)=>b[i]===v)) return {ext:'png',mime:'image/png'};
    if (b.length>=3 && b[0]===255 && b[1]===216 && b[2]===255) return {ext:'jpg',mime:'image/jpeg'};
    if (b.length>=6 && ['GIF87a','GIF89a'].includes(s(0,6))) return {ext:'gif',mime:'image/gif'};
    if (b.length>=12 && s(0,4)==='RIFF' && s(8,4)==='WEBP') return {ext:'webp',mime:'image/webp'};
    if (b.length>=8 && ['ftyp','free','skip','wide'].includes(s(4,4)))return isoMedia(b) || {ext:null,mime:'unknown'};
    if (b.length>=4 && [26,69,223,163].every((v,i)=>b[i]===v))return webmMedia(b) || {ext:null,mime:'unknown'};
    return {ext:null,mime:'unknown'};
  }
  function inspect(bytes, mime, url) {
    const detected=signature(bytes), declared=String(mime || '').split(';')[0].trim().toLowerCase();
    if (!detected.ext) throw error('UNSUPPORTED_MEDIA',detected.reason==='encrypted-media'?'암호화된 미디어는 지원하지 않습니다.':'지원하는 미디어 파일 구조가 아닙니다 ('+detected.mime+').');
    if (declared==='text/html' || declared==='application/xhtml+xml') throw error('UNSUPPORTED_MEDIA','서버가 미디어 대신 HTML을 반환했습니다.');
    if (streamMedia(url,declared))throw error('UNSUPPORTED_MEDIA','스트리밍 목록이나 분할 파일은 지원하지 않습니다.');
    const urlExt=new URL(url).pathname.match(/\.([a-z0-9]+)$/i)?.[1]?.toLowerCase() || '';
    const normal=x=>x==='jpeg'?'jpg':x;
    const mismatches=[];
    if (normal(urlExt)!==detected.ext)mismatches.push('url-extension');
    if (declared!==detected.mime)mismatches.push('response-mime');
    return {...detected,mediaKind:detected.mediaKind || 'image',responseMimeType:declared,urlExtension:urlExt,mismatches};
  }
  function actualName(path) {return String(path || '').replace(/\\/g,'/').split('/').pop();}
  function localManifest(job) {
    return {schemaVersion:1,kind:'aru-local-body-download',source:job.source,runId:job.id,createdAt:job.createdAt,finishedAt:job.finishedAt || null,
      status:job.status,requestedFolder:job.folder,bodySelector:job.bodySelector,counts:job.counts,unsupported:job.unsupported,
      images:job.images.map(x=>({...x,filename:x.status==='complete'?actualName(x.actualPath):null})),
      notice:'로컬 저장 기록입니다. 공개 메타데이터나 재배포 허가가 아닙니다.'};
  }
  Object.assign(D,{HOSTS,JOB_KEY,error,article,mediaUrl,safeName,folder,originalFilename,numbered,streamMedia,signature,inspect,actualName,localManifest});
})(globalThis);

whale/features/body-download/browser-api.source:
(function(root){
  'use strict';
  const D=root.AruBodyDownload, promise=!!root.browser?.runtime, api=promise?root.browser:root.chrome;
  function call(target, method, ...args) {
    if(!target || typeof target[method]!=='function')return Promise.reject(D.error('API_UNAVAILABLE','브라우저 기능을 사용할 수 없습니다: '+method));
    if(promise) {try{return Promise.resolve(target[method](...args));}catch(err){return Promise.reject(err);}}
    return new Promise((resolve,reject)=>{try{target[method](...args,value=>{const err=api.runtime.lastError;if(err)reject(D.error('BROWSER_API',err.message));else resolve(value);});}catch(err){reject(err);}});
  }
  async function options(){const value=await call(api.storage.sync,'get',['enabled','aruBodyDownloadOptions']);return (value.enabled===undefined || value.enabled===true) && value.aruBodyDownloadOptions?.enabled===true;}
  async function readJob(id){const stored=await call(api.storage.local,'get',[D.JOB_KEY,'aruBodyDownloadErrorV1']);const current=stored[D.JOB_KEY] || null;return id && current?.id!==id?stored.aruBodyDownloadErrorV1 || null:current;}
  async function writeJob(job){await call(api.storage.local,'set',{[D.JOB_KEY]:job});}
  function own(item){const base=api?.runtime?.getURL?.('');return !!base && typeof item.url==='string' && item.url.startsWith('blob:'+base);}
  Object.assign(D,{api,call,options,readJob,writeJob,ownsDownload:own});
})(globalThis);

whale/features/body-download/engine.js.source:
(function(root){
  'use strict';
  const D=root.AruBodyDownload;
  const sleep=(ms,signal)=>new Promise((resolve,reject)=>{
    if(signal?.aborted){reject(D.error('CANCELLED','취소했습니다.'));return;}
    const cleanup=()=>signal?.removeEventListener('abort',abort);
    const timer=setTimeout(()=>{cleanup();resolve();},ms);
    const abort=()=>{clearTimeout(timer);cleanup();reject(D.error('CANCELLED','취소했습니다.'));};
    signal?.addEventListener('abort',abort,{once:true});
  });
  async function fetchImage(url,{signal,fetchFn=root.fetch,maxBytes=20*1024*1024,timeoutMs=20000}={}){
    D.mediaUrl(url);
    const ctl=new AbortController(),abort=()=>ctl.abort();signal?.addEventListener('abort',abort,{once:true});
    if(signal?.aborted)ctl.abort();const timer=setTimeout(abort,timeoutMs);
    try{
      const response=await fetchFn(url,{method:'GET',credentials:'omit',redirect:'error',cache:'no-store',signal:ctl.signal});
      if(response.redirected || (response.url && response.url!==url))throw D.error('REDIRECT','주소 이동을 허용하지 않습니다.');
      if(!response.ok){const err=D.error([401,403,429].includes(response.status)?'ACCESS_DENIED':'HTTP','미디어 요청 실패 (HTTP '+response.status+').');err.retryable=response.status>=500;throw err;}
      if(Number(response.headers.get('content-length'))>maxBytes)throw D.error('TOO_LARGE','파일당 20 MiB 상한을 넘었습니다.');
      const chunks=[];let length=0;
      if(response.body?.getReader){const reader=response.body.getReader();try{while(true){const part=await reader.read();if(part.done)break;length+=part.value.byteLength;if(length>maxBytes){await reader.cancel();throw D.error('TOO_LARGE','파일당 20 MiB 상한을 넘었습니다.');}chunks.push(part.value);}}finally{reader.releaseLock();}}
      else {const buffer=new Uint8Array(await response.arrayBuffer());length=buffer.length;chunks.push(buffer);}
      if(length>maxBytes)throw D.error('TOO_LARGE','파일당 20 MiB 상한을 넘었습니다.');
      const bytes=new Uint8Array(length);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}
      const type=D.inspect(bytes,response.headers.get('content-type'),url);
      const digest=await root.crypto.subtle.digest('SHA-256',bytes);
      const sha256=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');
      return {bytes,type,sha256,responseUrl:response.url || url};
    }catch(err){
      if(ctl.signal.aborted)throw D.error(signal?.aborted?'CANCELLED':'TIMEOUT',signal?.aborted?'취소했습니다.':'미디어 응답 시간이 초과되었습니다.');
      if(err instanceof TypeError)err.retryable=true;
      throw err;
    }finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}
  }
  class DownloadRunner{
    constructor({api=D.api,call=D.call,fetchFn=root.fetch,persist=D.writeJob,onProgress=()=>{},isEnabled=D.options,intervalMs=300,timeoutMs=120000}={}){
      Object.assign(this,{api,call,fetchFn,persist,onProgress,isEnabled,intervalMs,timeoutMs});this.running=false;this.downloadId=null;
    }
    async cancel(){this.cancelled=true;this.controller?.abort();if(this.downloadId!==null)try{await this.call(this.api.downloads,'cancel',this.downloadId);}catch(_){} }
    async saveBytes(bytes,mime,path,signal,onStarted=()=>{}){
      if(signal?.aborted)throw D.error('CANCELLED','취소했습니다.');
      const blobUrl=root.URL.createObjectURL(new Blob([bytes],{type:mime}));
      let id=null,changed,timer,abort;
      try{
        // Listen before starting: small local blobs may finish before download() resolves.
        let wake=()=>{};
        changed=delta=>{if(delta.id===id)wake();};this.api.downloads.onChanged.addListener(changed);
        id=await this.call(this.api.downloads,'download',{url:blobUrl,filename:path,conflictAction:'uniquify',saveAs:false});
        this.downloadId=id;await onStarted(id);
        const item=await new Promise((resolve,reject)=>{
          let checking=false,again=false,finished=false;
          const fail=err=>{if(!finished){finished=true;reject(err);}};
          const check=async()=>{
            if(checking){again=true;return;}checking=true;
            try{
              do{again=false;const found=(await this.call(this.api.downloads,'search',{id}))[0];
                if(!found)throw D.error('DOWNLOAD_MISSING','다운로드 결과를 조회할 수 없습니다.');
                if(found.state==='complete'){
                  if(found.exists===false || !found.filename)throw D.error('FILE_MISSING','브라우저가 저장 파일을 확인하지 못했습니다.');
                  if(Number.isFinite(found.fileSize) && found.fileSize!==bytes.length)throw D.error('SIZE_MISMATCH','저장된 파일 크기가 원본 바이트와 다릅니다.');
                  if(!finished){finished=true;resolve(found);}return;
                }
                if(found.state==='interrupted'){const err=D.error('DOWNLOAD_INTERRUPTED','다운로드 중단: '+(found.error || 'unknown'));err.retryable=/^(?:NETWORK_|SERVER_FAILED|FILE_TRANSIENT_ERROR)/.test(found.error || '');throw err;}
              }while(again && !finished);
            }catch(err){fail(err);}finally{checking=false;}
          };
          wake=check;timer=setTimeout(()=>fail(D.error('DOWNLOAD_TIMEOUT','저장 완료 확인 시간이 초과되었습니다.')),this.timeoutMs);
          abort=()=>fail(D.error('CANCELLED','취소했습니다.'));signal?.addEventListener('abort',abort,{once:true});
          if(signal?.aborted)abort();else check();
        });
        return item;
      }catch(err){if(id!==null)try{await this.call(this.api.downloads,'cancel',id);}catch(_){}throw err;}
      finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);if(changed)this.api.downloads.onChanged.removeListener(changed);this.downloadId=null;root.URL.revokeObjectURL(blobUrl);}
    }
    async notify(job){await this.persist(job);this.onProgress(job);}
    async run(job){
      if(this.running)throw D.error('BUSY','이미 다운로드 중입니다.');
      if(job.status!=='prepared')throw D.error('STATE','새 확인 화면에서 다운로드를 시작해 주세요. 자동 재개하지 않습니다.');
      // Reserve before the asynchronous settings read so simultaneous starts cannot race.
      this.running=true;this.cancelled=false;
      try{if(!await this.isEnabled())throw D.error('DISABLED','전체 확장과 다운로드 옵션이 꺼져 있습니다.');
        if(this.cancelled)throw D.error('CANCELLED','취소했습니다.');
      }catch(err){this.running=false;throw err;}
      this.controller=new AbortController();const signal=this.controller.signal;
      try{
        job.status='running';await this.notify(job);
        let blocked=false;
        for(const image of job.images){
          if(this.cancelled || !await this.isEnabled()){this.cancelled=true;break;}
          if(blocked){image.status='blocked';continue;}
          image.status='processing';job.currentIndex=image.index;
          for(let attempt=1;attempt<=2;attempt++){
            image.attempts=attempt;image.status='processing';await this.notify(job);
            try{
              const fetched=await fetchImage(image.originalUrl,{signal,fetchFn:this.fetchFn});
              const {type,bytes,sha256}=fetched;
              Object.assign(image,{mediaKind:type.mediaKind,mimeType:type.mime,responseMimeType:type.responseMimeType,urlExtension:type.urlExtension,mismatches:type.mismatches,
                responseUrl:fetched.responseUrl,byteLength:bytes.length,sha256,requestedFilename:D.numbered(image.index,type.ext)});
              const path=job.folder+'/'+image.requestedFilename;
              const item=await this.saveBytes(bytes,type.mime,path,signal,async id=>{image.downloadId=id;image.status='saving';await this.notify(job);});
              Object.assign(image,{status:'complete',actualPath:item.filename,filename:D.actualName(item.filename),downloadMimeType:item.mime || null,
                filenameMatchesRequest:D.actualName(item.filename)===image.requestedFilename,
                folderMatchesRequest:item.filename.replace(/\\/g,'/').endsWith('/'+path)});
              if(item.mime && item.mime!==type.mime)image.mismatches.push('download-mime');
              image.error=null;break;
            }catch(err){
              image.error={code:err.code || 'NETWORK',message:err.message};
              if(err.code==='CANCELLED'){image.status='cancelled';break;}
              if(err.code==='ACCESS_DENIED'){image.status='failed';blocked=true;break;}
              if(err.retryable && attempt<2){await sleep(600,signal).catch(()=>{});continue;}
              image.status=err.code==='UNSUPPORTED_MEDIA'?'unsupported':'failed';break;
            }
          }
          await this.notify(job);if(this.cancelled)break;
          await sleep(this.intervalMs,signal).catch(()=>{});
        }
        for(const image of job.images)if(['pending','processing','saving'].includes(image.status))image.status='cancelled';
        job.status=this.cancelled?'cancelled':blocked?'blocked':job.images.some(x=>x.status!=='complete')?'partial':'complete';
        job.currentIndex=null;job.finishedAt=new Date().toISOString();await this.notify(job);
        // Cancellation ends image requests. Save only the local record for the already-approved run.
        await this.saveManifest(job);
        return job;
      }catch(err){job.status='interrupted';job.error=err.message;await this.notify(job).catch(()=>{});throw err;}
      finally{this.running=false;this.controller=null;}
    }
    async saveManifest(job){
      const bytes=new TextEncoder().encode(JSON.stringify(D.localManifest(job),null,2)+'\n');
      try{
        const item=await this.saveBytes(bytes,'application/json',job.folder+'/manifest.json');
        job.manifest={status:'complete',actualPath:item.filename,filename:D.actualName(item.filename),filenameMatchesRequest:D.actualName(item.filename)==='manifest.json'};
      }catch(err){job.manifest={status:'failed',error:err.message};}
      await this.notify(job);
    }
    async recover(job){
      if(!['running','cancelling'].includes(job.status))return job;
      for(const image of job.images){
        if(!['processing','saving','pending'].includes(image.status))continue;
        if(image.downloadId!=null){try{
          const item=(await this.call(this.api.downloads,'search',{id:image.downloadId}))[0];
          if(item?.state==='complete' && item.exists!==false && item.filename && item.fileSize===image.byteLength){
            Object.assign(image,{status:'complete',actualPath:item.filename,filename:D.actualName(item.filename),filenameMatchesRequest:D.actualName(item.filename)===image.requestedFilename});continue;
          }
          if(item?.state==='in_progress')await this.call(this.api.downloads,'cancel',item.id);
        }catch(_){} }
        image.status='interrupted';
      }
      job.status='interrupted';job.currentIndex=null;job.error='실행 화면이 닫히거나 다시 열렸습니다. 자동 재개하지 않습니다. 아래에서 기록을 저장하거나 새로 실행해 주세요.';
      await this.notify(job);return job;
    }
  }
  Object.assign(D,{fetchImage,DownloadRunner});
})(globalThis);

whale/features/body-download/ui.js.source:
(function(root){
  'use strict';
  const D=root.AruBodyDownload, $=id=>document.getElementById(id);
  let job=null,runner=null,lease=null;
  const labels={prepared:'실행 전',running:'다운로드 중',complete:'미디어 저장 완료',partial:'일부 파일 저장 실패',blocked:'접근 제한으로 미디어 요청 중지',cancelled:'취소됨',interrupted:'중단됨',error:'실행할 수 없습니다'};
  function render(value){
    job=value;if(!job.source){$('article-title').textContent='본문을 확인할 수 없습니다';$('error').hidden=false;$('error').textContent=job.error || '게시글에서 다시 실행해 주세요.';return;}
    $('article-title').textContent=job.source.title;$('source').textContent='게시글 '+job.source.articleId+' · '+job.source.url;
    $('found').textContent=job.counts.bodyMedia-job.counts.unsupported;$('unique').textContent=job.images.length;
    $('unsupported').textContent=job.counts.unsupported+job.images.filter(x=>x.status==='unsupported').length;$('folder').textContent=job.folder;
    const complete=job.images.filter(x=>x.status==='complete').length, failed=job.images.filter(x=>['failed','unsupported','blocked'].includes(x.status)).length;
    const processed=job.images.filter(x=>['complete','failed','unsupported'].includes(x.status)).length;
    const percentage=job.images.length?Math.round(processed/job.images.length*100):0;
    $('percentage').textContent=percentage+'%';$('progress').value=percentage;
    $('counts').textContent='전체 '+job.images.length+'개 · 완료 '+complete+'개 · 실패/제외 '+failed+'개 · 미완료 '+(job.images.length-complete-failed)+'개';
    const current=job.images.find(x=>x.index===job.currentIndex);$('current').textContent=current?'현재 처리: '+(current.requestedFilename || String(current.index).padStart(3,'0'))+' · 시도 '+current.attempts+'/2':'';
    $('status').textContent=(labels[job.status] || job.status)+(job.manifest?.status==='complete'?' · '+job.manifest.filename+' 저장됨':job.manifest?.status==='failed'?' · 기록 저장 실패':'');
    $('error').hidden=!job.error && job.manifest?.status!=='failed';$('error').textContent=job.error || job.manifest?.error || '';
    $('start').disabled=job.status!=='prepared' || !job.images.length;
    $('cancel').textContent=['running','cancelling'].includes(job.status)?'다운로드 취소':'닫기';
    $('record').hidden=!['interrupted','partial','cancelled','blocked'].includes(job.status) && job.manifest?.status!=='failed';
    // Details are populated on demand; progress updates do not rebuild thousands of rows.
    if($('results').open)renderResults();
  }
  function renderResults(){const fragment=document.createDocumentFragment();for(const image of job?.images || []){const li=document.createElement('li');li.textContent=(image.filename || image.requestedFilename || String(image.index).padStart(3,'0'))+' · '+image.status+(image.error?' · '+image.error.message:'')+(image.filenameMatchesRequest===false?' · 브라우저가 파일명을 변경함':'');fragment.append(li);}$('file-results').replaceChildren(fragment);}
  $('results').addEventListener('toggle',()=>{if($('results').open)renderResults();});
  async function load(){
    const id=new URLSearchParams(root.location.search).get('job'), stored=await D.readJob(id);
    if(!stored || stored.id!==id)throw D.error('JOB','이 실행 기록이 없거나 다른 다운로드 화면이 열렸습니다. 게시글에서 다시 실행해 주세요.');
    job=stored;runner=new D.DownloadRunner({onProgress:render});
    // Lock held for the lifetime of this manager, including before confirmation.
    if(!root.navigator.locks)throw D.error('LOCK_UNAVAILABLE','중복 실행 방지 기능을 사용할 수 없는 브라우저입니다.');
    let readyResolve;const ready=new Promise(resolve=>{readyResolve=resolve;});
    const hold=new Promise(resolve=>{lease=resolve;});
    root.navigator.locks.request('aru-body-download-manager',{ifAvailable:true},async lock=>{readyResolve(!!lock);if(lock)await hold;}).catch(()=>readyResolve(false));
    if(!await ready)throw D.error('BUSY','다른 다운로드 화면이 이미 열려 있습니다. 그 화면에서 진행해 주세요.');
    await runner.recover(job);render(job);
  }
  $('start').addEventListener('click',async event=>{
    if(!event.isTrusted || !job || runner?.running)return;
    $('start').disabled=true;
    try{
      if(!await D.options())throw D.error('DISABLED','전체 확장과 다운로드 옵션을 켜 주세요.');
      const sourceTab=await D.call(D.api.tabs,'get',job.sourceTabId);
      if(D.article(sourceTab.url).url!==job.source.url)throw D.error('NAVIGATED','원본 탭의 게시글이 변경되었습니다. 다시 실행해 주세요.');
      const fresh=await D.call(D.api.tabs,'sendMessage',job.sourceTabId,{type:'aru-body-download:collect',url:job.source.url},{frameId:0});
      if(!fresh?.ok || JSON.stringify(fresh.result.images.map(x=>x.originalUrl))!==JSON.stringify(job.images.map(x=>x.originalUrl)))throw D.error('BODY_CHANGED','본문 미디어 목록이 변경되었습니다. 게시글에서 다시 실행해 주세요.');
      await runner.run(job);
    }catch(err){$('error').hidden=false;$('error').textContent=err.message;$('start').disabled=job.status!=='prepared';}
  });
  $('cancel').addEventListener('click',async event=>{
    if(!event.isTrusted)return;
    if(runner?.running){$('cancel').disabled=true;await runner.cancel();$('cancel').disabled=false;}
    else {if(job?.status==='prepared'){job.status='cancelled';await D.writeJob(job);}lease?.();root.close();}
  });
  $('record').addEventListener('click',async event=>{if(!event.isTrusted || !runner || runner.running)return;$('record').disabled=true;await runner.saveManifest(job);$('record').disabled=false;});
  D.api?.storage.onChanged.addListener((changes,area)=>{if(area==='sync' && (changes.enabled || changes.aruBodyDownloadOptions))D.options().then(active=>{if(!active && runner?.running)runner.cancel();}).catch(()=>runner?.cancel());});
  root.addEventListener('beforeunload',event=>{if(runner?.running){event.preventDefault();event.returnValue='';}});
  load().catch(err=>{$('error').hidden=false;$('error').textContent=err.message;$('start').disabled=true;});
})(globalThis);

